// Package mpin implements the MPin protocol.
package mpin

import (
	"errors"

	"code.miracl.com/maas/maas/src/lib/gomiracl"
	"code.miracl.com/maas/maas/src/lib/gomiracl/curve"
	"code.miracl.com/maas/maas/src/lib/gomiracl/rand"
	"code.miracl.com/maas/maas/src/lib/gomiracl/wrap"
)

var (
	errNoShares          = errors.New("need at least one share")
	errInvalidSecretSize = errors.New("invalid secret size")
)

// Curve is elliptic curve that supports the MPin protocol.
type Curve interface {
	curve.Curve

	FieldSize() int
	PGroupSize() int
	GetRandomSecret(rng *rand.Rand) (secret []byte, err error)
	NewServerSecretShare(masterSecret []byte) (share []byte, err error)
	NewClientSecretShare(masterSecret, id []byte) (share []byte, err error)
	NewTimePermitShare(hash gomiracl.Hash, date int, masterSecret, id []byte) (timePermit []byte, err error)
	RecombineG1(share1, share2 []byte) (secret []byte, err error)
	RecombineG2(share1, share2 []byte) (secret []byte, err error)
	ExtractPin(hash gomiracl.Hash, id []byte, pin int, clientSecret []byte) (token []byte, err error)
	ClientOnePass(hash gomiracl.Hash, date int, id []byte, rng *rand.Rand, x []byte, pin int, token, timePermit, msg []byte, time int) (xOut, v, u, ut, y []byte, err error)
	ServerOnePass(hash gomiracl.Hash, date int, serverSecret, u, ut, v, id, msg []byte, time int, pa []byte) (HID, HTID, y []byte, err error)
	ClientPass1(hash gomiracl.Hash, date int, id []byte, rng *rand.Rand, x []byte, pin int, token, timePermit []byte) (xOut, sec, u, ut []byte, err error)
	ClientPass2(x, y, sec []byte) (vOut []byte, err error)
	ServerPass1(hash gomiracl.Hash, date int, id []byte) (hid, htid []byte)
	ServerPass2(date int, hid, htid, y, serverSecret, u, ut, vOut, pa []byte) (err error)
	Precompute(token, id, pub []byte) (g1, g2 []byte, err error)
	GetG1Multiple(rng *rand.Rand, opType int, x, g []byte) (xOut, w []byte, err error)
	ServerKey(hash gomiracl.Hash, z, serverSecret, w, p, i, u, ut []byte) (k []byte, err error)
	ClientKey(hash gomiracl.Hash, g1, g2 []byte, pin int, r, x, p, t []byte) (k []byte, err error)
	GetDVSKeyPair(rng *rand.Rand, z []byte) (zOut, pub []byte, err error)
}

// MasterSecret is the master secret.
type MasterSecret struct {
	secret []byte
	curve  Curve
}

// NewMasterSecret returns new MasterSecret.
func NewMasterSecret(c Curve, rng *rand.Rand) (*MasterSecret, error) {
	secret, err := c.GetRandomSecret(rng)
	if err != nil {
		return nil, err
	}

	return &MasterSecret{secret: secret, curve: c}, nil
}

// MasterSecretFromBytes returns new MasterSecret from already generated byte slice
// Returns error if the size is different than expected master secret size for
// the specified curve.
func MasterSecretFromBytes(c Curve, secret []byte) (*MasterSecret, error) {
	if len(secret) != c.PGroupSize() {
		return nil, errInvalidSecretSize
	}

	return &MasterSecret{secret: secret, curve: c}, nil
}

// Secret returns the secret as bytes.
func (ms *MasterSecret) Secret() []byte {
	return ms.secret
}

// Curve returns the curve.
func (ms *MasterSecret) Curve() Curve {
	return ms.curve
}

// Destroy overwrites the secret.
func (ms *MasterSecret) Destroy() {
	gomiracl.CleanMemory(ms.secret)
}

// ServerSecretShare is the server secret.
type ServerSecretShare []byte

// NewServerSecretShare creates new Server Secret Share.
func (ms *MasterSecret) NewServerSecretShare() (ServerSecretShare, error) {
	secret, err := ms.curve.NewServerSecretShare(ms.secret)
	if err != nil {
		return nil, err
	}

	return secret, nil
}

// Secret returns the secret as bytes.
func (ss ServerSecretShare) Secret() []byte {
	return []byte(ss)
}

// Destroy overwrites the secret.
func (ss ServerSecretShare) Destroy() {
	gomiracl.CleanMemory(ss)
}

// ServerSecret is the server secret.
type ServerSecret struct {
	secret []byte
	curve  Curve
}

// NewServerSecret returns ServerSecret by recombining two Server Secret Shares.
func NewServerSecret(c Curve, shares ...ServerSecretShare) (*ServerSecret, error) {
	if len(shares) < 1 {
		return nil, errNoShares
	}

	secret := shares[0]

	for i := 1; i < len(shares); i++ {
		var err error

		secret, err = c.RecombineG2(secret, shares[i])
		if err != nil {
			return nil, err
		}
	}

	return &ServerSecret{secret: secret, curve: c}, nil
}

// ServerPass1Result is the result of Pass1 on the client side.
type ServerPass1Result struct{ HID, HTID, Y []byte }

// Destroy overwrites the secret.
func (r *ServerPass1Result) Destroy() {
	gomiracl.CleanMemory(r.Y)
}

// Pass1 performes MPin Pass1 for the server side.
func (ss *ServerSecret) Pass1(id []byte, hash gomiracl.Hash, rng *rand.Rand) (*ServerPass1Result, error) {
	return ss.Pass1WithTimePermit(id, 0, hash, rng)
}

// Pass1WithTimePermit performes MPin Pass1 for the server side with TimePermits.
func (ss *ServerSecret) Pass1WithTimePermit(id []byte, date int, hash gomiracl.Hash, rng *rand.Rand) (*ServerPass1Result, error) {
	hid, htid := ss.curve.ServerPass1(hash, date, id)

	y, err := ss.curve.GetRandomSecret(rng)
	if err != nil {
		return nil, err
	}

	return &ServerPass1Result{hid, htid, y}, nil
}

// Pass2 performes MPin Pass2 for the server side.
func (ss *ServerSecret) Pass2(hid, y, u, v []byte) error {
	return ss.curve.ServerPass2(0, hid, nil, y, ss.secret, u, nil, v, nil)
}

// Pass2WithTimePermit performes MPin Pass2 for the server side with TimePermits.
func (ss *ServerSecret) Pass2WithTimePermit(date int, hid, htid, y, u, ut, v, pa []byte) error {
	return ss.curve.ServerPass2(date, hid, htid, y, ss.secret, u, ut, v, pa)
}

// Pass2WithDVS performes MPin Pass2 for the server side with DVS.
func (ss *ServerSecret) Pass2WithDVS(hid, y, u, v, pa []byte) error {
	return ss.curve.ServerPass2(0, hid, nil, y, ss.secret, u, nil, v, pa)
}

// ServerOnePassResult is the result of One Pass.
type ServerOnePassResult struct{ HID, HTID, Y []byte }

// Destroy overwrites the secret.
func (r *ServerOnePassResult) Destroy() {
	if r == nil {
		return
	}

	gomiracl.CleanMemory(r.Y)
}

// OnePass performes one pass server side validation.
func (ss *ServerSecret) OnePass(id []byte, hash gomiracl.Hash, time int, u, v []byte) (*ServerOnePassResult, error) {
	hid, htid, y, err := ss.curve.ServerOnePass(hash, 0, ss.secret, u, nil, v, id, nil, time, nil)
	if err != nil {
		return nil, err
	}

	return &ServerOnePassResult{hid, htid, y}, nil
}

// OnePassWithTimePermit performes one pass server side validation with TimePermits.
func (ss *ServerSecret) OnePassWithTimePermit(id []byte, hash gomiracl.Hash, date, time int, u, ut, v []byte) (*ServerOnePassResult, error) {
	hid, htid, y, err := ss.curve.ServerOnePass(hash, date, ss.secret, u, ut, v, id, nil, time, nil)
	if err != nil {
		return nil, err
	}

	return &ServerOnePassResult{hid, htid, y}, nil
}

// OnePassWithDVS performes one pass server side validation with DVS.
func (ss *ServerSecret) OnePassWithDVS(id, msg []byte, time int, u, v, pa []byte, hash gomiracl.Hash) (*ServerOnePassResult, error) {
	hid, htid, y, err := ss.curve.ServerOnePass(hash, 0, ss.secret, u, nil, v, id, msg, time, pa)
	if err != nil {
		return nil, err
	}

	return &ServerOnePassResult{hid, htid, y}, nil
}

// ServerKey calculates key on Server side for MPin Full.
func (ss *ServerSecret) ServerKey(hash gomiracl.Hash, z, w, p, i, u, ut []byte) ([]byte, error) {
	return ss.curve.ServerKey(hash, z, ss.Secret(), w, p, i, u, ut)
}

// Secret returns the secret as bytes.
func (ss *ServerSecret) Secret() []byte {
	return ss.secret
}

// Destroy overwrites the secret.
func (ss *ServerSecret) Destroy() {
	gomiracl.CleanMemory(ss.secret)
}

// ClientSecretShare is the server secret.
type ClientSecretShare []byte

// NewClientSecretShare creates new Client Secret Share.
func (ms *MasterSecret) NewClientSecretShare(hashedID []byte) (ClientSecretShare, error) {
	secret, err := ms.curve.NewClientSecretShare(ms.secret, hashedID)
	if err != nil {
		return nil, err
	}

	return secret, nil
}

// Secret returns the secret as bytes.
func (ss ClientSecretShare) Secret() []byte {
	return []byte(ss)
}

// Destroy overwrites the secret.
func (ss ClientSecretShare) Destroy() {
	gomiracl.CleanMemory(ss)
}

// ClientToken is the ClientSecret with extracted pin.
type ClientToken struct {
	secret []byte
	curve  Curve
}

// NewClientToken returns new ClientToken.
func NewClientToken(secret []byte, c Curve) *ClientToken {
	return &ClientToken{secret: secret, curve: c}
}

// GetClientToken returns new ClientToken by recreating two
// ClientSecretShares and extracting pin from the ClientSecret.
func GetClientToken(id []byte, pin int, hash gomiracl.Hash, c Curve, shares ...ClientSecretShare) (*ClientToken, error) {
	if len(shares) < 1 {
		return nil, errNoShares
	}

	secret := shares[0]

	for i := 1; i < len(shares); i++ {
		var err error

		secret, err = c.RecombineG1(secret, shares[i])
		if err != nil {
			return nil, err
		}
	}

	defer gomiracl.CleanMemory(secret)

	token, err := c.ExtractPin(hash, id, pin, secret)
	if err != nil {
		return nil, err
	}

	return &ClientToken{secret: token, curve: c}, nil
}

// GetDVSClientToken returns new Client token from key-escrow less secret.
func GetDVSClientToken(dvsID []byte, pin int, hash gomiracl.Hash, z []byte, c Curve, shares ...ClientSecretShare) (*ClientToken, error) {
	if len(shares) < 1 {
		return nil, errNoShares
	}

	secret := shares[0]

	for i := 1; i < len(shares); i++ {
		var err error

		secret, err = c.RecombineG1(secret, shares[i])
		if err != nil {
			return nil, err
		}
	}

	defer gomiracl.CleanMemory(secret)

	_, secret, err := c.GetG1Multiple(nil, 0, z, secret)
	if err != nil {
		return nil, err
	}

	token, err := c.ExtractPin(hash, dvsID, pin, secret)
	if err != nil {
		return nil, err
	}

	return &ClientToken{secret: token, curve: c}, nil
}

// ClientPass1Proof is the result of Pass1 on the client side.
type ClientPass1Proof struct{ X, SEC, U, UT []byte }

// Destroy overwrites the secret.
func (p *ClientPass1Proof) Destroy() {
	gomiracl.CleanMemory(p.X)
	gomiracl.CleanMemory(p.SEC)
	gomiracl.CleanMemory(p.U)
	gomiracl.CleanMemory(p.UT)
}

// Pass1 performes MPin Pass1 for the client side.
func (token *ClientToken) Pass1(id []byte, pin int, hash gomiracl.Hash, rng *rand.Rand) (*ClientPass1Proof, error) {
	x, sec, u, ut, err := token.curve.ClientPass1(hash, 0, id, rng, nil, pin, token.Secret(), nil)
	if err != nil {
		return nil, err
	}

	return &ClientPass1Proof{x, sec, u, ut}, nil
}

// Pass1WithTimePermit performes MPin Pass1 for the client side with TimePermits.
func (token *ClientToken) Pass1WithTimePermit(id []byte, pin, date int, tp TimePermit, hash gomiracl.Hash, rng *rand.Rand) (*ClientPass1Proof, error) {
	x, sec, u, ut, err := token.curve.ClientPass1(hash, date, id, rng, nil, pin, token.Secret(), tp.Secret())
	if err != nil {
		return nil, err
	}

	return &ClientPass1Proof{x, sec, u, ut}, nil
}

// ClientPass2Proof is the result of Pass2 on the client side.
type ClientPass2Proof struct{ V []byte }

// Destroy overwrites the secret.
func (p *ClientPass2Proof) Destroy() {
	gomiracl.CleanMemory(p.V)
}

// Pass2 performes MPin Pass2 for the client side.
func (token *ClientToken) Pass2(x, y, sec []byte) (*ClientPass2Proof, error) {
	v, err := token.curve.ClientPass2(x, y, sec)
	if err != nil {
		return nil, err
	}

	return &ClientPass2Proof{v}, nil
}

// OnePassProof is the result of OnePass on the client side.
type OnePassProof struct{ X, V, U, UT, Y []byte }

// Destroy overwrites the secret.
func (p *OnePassProof) Destroy() {
	gomiracl.CleanMemory(p.X)
	gomiracl.CleanMemory(p.V)
	gomiracl.CleanMemory(p.U)
	gomiracl.CleanMemory(p.UT)
	gomiracl.CleanMemory(p.Y)
}

// OnePass performes MPin One Pass for the client side.
func (token *ClientToken) OnePass(id []byte, pin, time int, hash gomiracl.Hash, rng *rand.Rand) (*OnePassProof, error) {
	return token.OnePassWithTimePermit(id, pin, 0, time, nil, hash, rng)
}

// OnePassWithDVS performes MPin One Pass for the client side with DVS.
func (token *ClientToken) OnePassWithDVS(id []byte, pin int, msg []byte, time int, hash gomiracl.Hash, rng *rand.Rand) (*OnePassProof, error) {
	xout, v, u, ut, y1, err := token.curve.ClientOnePass(hash, 0, id, rng, nil, pin, token.Secret(), nil, msg, time)
	if err != nil {
		return nil, err
	}

	return &OnePassProof{xout, v, u, ut, y1}, nil
}

// OnePassWithTimePermit performes MPin One Pass for the client side with TimePermits.
func (token *ClientToken) OnePassWithTimePermit(id []byte, pin, date, time int, tp TimePermit, hash gomiracl.Hash, rng *rand.Rand) (*OnePassProof, error) {
	xout, v, u, ut, y1, err := token.curve.ClientOnePass(hash, date, id, rng, nil, pin, token.Secret(), tp, nil, time)
	if err != nil {
		return nil, err
	}

	return &OnePassProof{xout, v, u, ut, y1}, nil
}

// FullPrecompute are the values returned by the precompute function.
type FullPrecompute struct{ G1, G2 []byte }

// Destroy overwrites the secret.
func (p *FullPrecompute) Destroy() {
	gomiracl.CleanMemory(p.G1)
	gomiracl.CleanMemory(p.G2)
}

// Precompute precomputes values for use by the client side of M-Pin Full.
func (token *ClientToken) Precompute(hashedID, pub []byte) (*FullPrecompute, error) {
	g1, g2, err := token.curve.Precompute(token.Secret(), hashedID, pub)
	if err != nil {
		return nil, err
	}

	return &FullPrecompute{g1, g2}, nil
}

// Secret returns the secret as bytes.
func (token *ClientToken) Secret() []byte {
	return token.secret
}

// Destroy overwrites the secret.
func (token *ClientToken) Destroy() {
	gomiracl.CleanMemory(token.secret)
}

// TimePermitShare is Time Permit Share.
type TimePermitShare []byte

// NewTimePermitShare returns new Time Permit.
func (ms *MasterSecret) NewTimePermitShare(hashedID []byte, date int, hash gomiracl.Hash) (TimePermitShare, error) {
	tp, err := ms.curve.NewTimePermitShare(hash, date, ms.secret, hashedID)
	if err != nil {
		return nil, err
	}

	return TimePermitShare(tp), nil
}

// Secret returns the secret as bytes.
func (tps TimePermitShare) Secret() []byte {
	return []byte(tps)
}

// Destroy overwrites the secret.
func (tps TimePermitShare) Destroy() {
	gomiracl.CleanMemory(tps)
}

// TimePermit is Time Permit.
type TimePermit []byte

// NewTimePermit returns new Time Permit.
func NewTimePermit(c Curve, shares ...TimePermitShare) (TimePermit, error) {
	if len(shares) < 1 {
		return nil, errNoShares
	}

	timePermit := shares[0]

	for i := 1; i < len(shares); i++ {
		var err error

		timePermit, err = c.RecombineG1(timePermit, shares[i])
		if err != nil {
			return nil, err
		}
	}

	return TimePermit(timePermit), nil
}

// Secret returns the secret as bytes.
func (tp TimePermit) Secret() []byte {
	return []byte(tp)
}

// Destroy overwrites the secret.
func (tp TimePermit) Destroy() {
	gomiracl.CleanMemory(tp)
}

// HashID hashes the identity for given curve.
func HashID(id []byte, hash gomiracl.Hash, c Curve) []byte {
	return wrap.HashID(int(hash), id, c.FieldSize())
}

// HashAll hashes the MPin transcript.
func HashAll(hash gomiracl.Hash, id, u, cu, y, v, r, w []byte, hSize int) []byte {
	return wrap.HashAll(int(hash), id, u, cu, y, v, r, w, hSize)
}
